insert into public.learning_lessons(slug,title,excerpt,lesson_type,duration_minutes,sort_order,status,category_id,content) select 'basics-first-live','Первый эфир — базовые принципы торговли','Записанный первый эфир: базовые принципы торговли, сигналы, первые сделки и фундамент дальнейшего обучения.','video',50,10,'published',id,'{"videoUrl":"","article":"Записанный первый эфир: базовые принципы торговли, сигналы, первые сделки и фундамент дальнейшего обучения.","examples":"Записанный первый эфир: базовые принципы торговли, сигналы, первые сделки и фундамент дальнейшего обучения.","practice":"Пересмотри эфир и выпиши 3 принципа, которые станут правилами твоего торгового процесса.","quiz":[{"id":"q1","type":"single_select","question":"Какая тема является основной для урока «Первый эфир — базовые принципы торговли»?","options":[{"value":"A","label":"Первый эфир — базовые принципы торговли","feedback":"Название и содержание урока прямо указывают на эту тему."},{"value":"B","label":"Разбор баланса и депозитных операций","feedback":"Эта тема не является основной темой данного материала."},{"value":"C","label":"Настройка профиля приложения","feedback":"Материал не посвящён настройке профиля приложения."},{"value":"D","label":"Администрирование пользователей","feedback":"Материал не посвящён административному разделу приложения."}],"correctValues":["A"],"hint":"Сверь формулировку вопроса с названием и кратким описанием урока."},{"id":"q2","type":"true_false","question":"Урок «Первый эфир — базовые принципы торговли» относится к разделу «Основы».","options":[{"value":"true","label":"Верно","feedback":"Урок действительно распределён в разделе «Основы»."},{"value":"false","label":"Неверно","feedback":"В структуре курса этот материал находится в разделе «Основы»."}],"correctValues":["true"],"hint":"Обрати внимание на учебный раздел, в котором расположен материал."},{"id":"q3","type":"multi_select","question":"Какие два утверждения прямо соответствуют описанию этого материала?","options":[{"value":"A","label":"Первый эфир — отправная точка программы.","feedback":"Это утверждение прямо следует из исходного описания материала."},{"value":"B","label":"В исходнике указана длительность 50 минут 7 секунд.","feedback":"Это утверждение также прямо указано в исходном описании."},{"value":"C","label":"Урок посвящён настройке интерфейса приложения.","feedback":"В исходном описании такого содержания нет."},{"value":"D","label":"Урок заменяет необходимость вести торговый журнал.","feedback":"Такого вывода исходный материал не содержит."}],"correctValues":["A","B"],"hint":"Выбирай только утверждения, которые можно подтвердить описанием этого урока."},{"id":"q4","type":"single_select","question":"Какой формат источника указан для материала «Первый эфир — базовые принципы торговли»?","options":[{"value":"A","label":"video","feedback":"В исходном списке материал указан как формат «video»."},{"value":"B","label":"software","feedback":"Это не формат данного источника."},{"value":"C","label":"dashboard","feedback":"Это не формат данного источника."},{"value":"D","label":"account","feedback":"Это не формат данного источника."}],"correctValues":["A"],"hint":"Смотри на тип исходного материала: видео, аудио, пост, книга или запись сессии."}],"keyTakeaway":"Первый эфир — отправная точка программы.","facts":["Первый эфир — отправная точка программы.","В исходнике указана длительность 50 минут 7 секунд."],"sourceTitle":"Первый эфир — базовые принципы торговли","sourceDuration":"50 минут 7 секунд","lessonFormat":"video","sourceOrder":1,"curriculumVersion":"V31 FULL"}'::jsonb from public.learning_categories where slug='basics' on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,lesson_type=excluded.lesson_type,duration_minutes=excluded.duration_minutes,sort_order=excluded.sort_order,status='published',category_id=excluded.category_id,content=excluded.content,updated_at=now();
