insert into public.learning_lessons(slug,title,excerpt,lesson_type,duration_minutes,sort_order,status,category_id,content) select 'technical-horizontal-levels','Горизонтальные уровни','Второй эфир: что такое горизонтальные уровни, как их находить и использовать; в эфире разобраны три сделки.','video',44,30,'published',id,'{"videoUrl":"","article":"Второй эфир: что такое горизонтальные уровни, как их находить и использовать; в эфире разобраны три сделки.","examples":"Второй эфир: что такое горизонтальные уровни, как их находить и использовать; в эфире разобраны три сделки.","practice":"Найди 3 зоны на графике и для каждой объясни, почему она важна.","quiz":[{"id":"q1","type":"single_select","question":"Какая тема является основной для урока «Горизонтальные уровни»?","options":[{"value":"A","label":"Горизонтальные уровни","feedback":"Название и содержание урока прямо указывают на эту тему."},{"value":"B","label":"Разбор баланса и депозитных операций","feedback":"Эта тема не является основной темой данного материала."},{"value":"C","label":"Настройка профиля приложения","feedback":"Материал не посвящён настройке профиля приложения."},{"value":"D","label":"Администрирование пользователей","feedback":"Материал не посвящён административному разделу приложения."}],"correctValues":["A"],"hint":"Сверь формулировку вопроса с названием и кратким описанием урока."},{"id":"q2","type":"true_false","question":"Урок «Горизонтальные уровни» относится к разделу «Технический анализ».","options":[{"value":"true","label":"Верно","feedback":"Урок действительно распределён в разделе «Технический анализ»."},{"value":"false","label":"Неверно","feedback":"В структуре курса этот материал находится в разделе «Технический анализ»."}],"correctValues":["true"],"hint":"Обрати внимание на учебный раздел, в котором расположен материал."},{"id":"q3","type":"multi_select","question":"Какие два утверждения прямо соответствуют описанию этого материала?","options":[{"value":"A","label":"Уровень рассматри