insert into public.learning_lessons(slug,title,excerpt,lesson_type,duration_minutes,sort_order,status,category_id,content) select 'technical-levels-zones','Уровни — это зоны, а не линии','Короткий материал о поддержке и сопротивлении: уровни нужно воспринимать как зоны и не входить только потому, что цена коснулась зоны.','video',2,40,'published',id,'{"videoUrl":"","article":"Короткий материал о поддержке и сопротивлении: уровни нужно воспринимать как зоны и не входить только потому, что цена коснулась зоны.","examples":"Короткий материал о поддержке и сопротивлении: уровни нужно воспринимать как зоны и не входить только потому, что цена коснулась зоны.","practice":"На графике отметь зоны поддержки/сопротивления и отдельно пометь ситуации, где одного касания недостаточно.","quiz":[{"id":"q1","type":"single_select","question":"Какая тема является основной для урока «Уровни — это зоны, а не линии»?","options":[{"value":"A","label":"Уровни — это зоны, а не линии","feedback":"Название и содержание урока прямо указывают на эту тему."},{"value":"B","label":"Разбор баланса и депозитных операций","feedback":"Эта тема не является основной темой данного материала."},{"value":"C","label":"Настройка профиля приложения","feedback":"Материал не посвящён настройке профиля приложения."},{"value":"D","label":"Администрирование пользователей","feedback":"Материал не посвящён административному разделу приложения."}],"correctValues":["A"],"hint":"Сверь формулировку вопроса с названием и кратким описанием урока."},{"id":"q2","type":"true_false","question":"Урок «Уровни — это зоны, а не линии» относится к разделу «Технический анализ».","options":[{"value":"true","label":"Верно","feedback":"Урок действительно распределён в разделе «Технический анализ»."},{"value":"false","label":"Неверно","feedback":"В структуре курса этот материал находится в разделе «Технический анализ»."}],"correctValues":["true"],"hint":"Обрати внимание на учебный раздел, в котором расположен материал."},{"id":"q3","type":"multi_select","question":"Какие два утверждения прямо соответствуют описанию этого материала?","options":[{"value":"A","label":"Ключевая идея — зона вместо идеальной линии.","feedback":"Это утверждение прямо следует из исходного описания материала."},{"value":"B","label":"Одного касания цены недостаточно как самостоятельного основания для входа.","feedback":"Это утверждение также прямо указано в исходном описании."},{"value":"C","label":"Урок посвящён настройке интерфейса приложения.","feedback":"В исходном описании такого содержания нет."},{"value":"D","label":"Урок заменяет необходимость вести торговый журнал.","feedback":"Такого вывода исходный материал не содержит."}],"correctValues":["A","B"],"hint":"Выбирай только утверждения, которые можно подтвердить описанием этого урока."},{"id":"q4","type":"single_select","question":"Какой формат источника указан для материала «Уровни — это зоны, а не линии»?","options":[{"value":"A","label":"video","feedback":"В исходном списке материал указан как формат «video»."},{"value":"B","label":"software","feedback":"Это не формат данного источника."},{"value":"C","label":"dashboard","feedback":"Это не формат данного источника."},{"value":"D","label":"account","feedback":"Это не формат данного источника."}],"correctValues":["A"],"hint":"Смотри на тип исходного материала: видео, аудио, пост, книга или запись сессии."}],"keyTakeaway":"Ключевая идея — зона вместо идеальной линии.","facts":["Ключевая идея — зона вместо идеальной линии.","Одного касания цены недостаточно как самостоятельного основания для входа."],"sourceTitle":"Уровни — это зоны, а не линии","sourceDuration":"1 минута 31 секунда","lessonFormat":"video","sourceOrder":4,"curriculumVersion":"V31 FULL"}'::jsonb from public.learning_categories where slug='technical' on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,lesson_type=excluded.lesson_type,duration_minutes=excluded.duration_minutes,sort_order=excluded.sort_order,status='published