insert into public.learning_lessons(slug,title,excerpt,lesson_type,duration_minutes,sort_order,status,category_id,content) select 'strategies-giant-candle','Giant Candle','OTC, таймфрейм 5 секунд, большая свеча против 3–5 предыдущих, вход в противоположную сторону, экспирация 3 секунды; только после новой ситуации.','post',1,180,'published',id,'{"videoUrl":"","article":"OTC, таймфрейм 5 секунд, большая свеча против 3–5 предыдущих, вход в противоположную сторону, экспирация 3 секунды; только после новой ситуации.","examples":"OTC, таймфрейм 5 секунд, большая свеча против 3–5 предыдущих, вход в противоположную сторону, экспирация 3 секунды; только после новой ситуации.","practice":"Не торгуй механику вслепую: сначала проверь, действительно ли появилась новая ситуация.","quiz":[{"id":"q1","type":"single_select","question":"Какая тема является основной для урока «Giant Candle»?","options":[{"value":"A","label":"Giant Candle","feedback":"Название и содержание урока прямо указывают на эту тему."},{"value":"B","label":"Разбор баланса и депозитных операций","feedback":"Эта тема не является основной темой данного материала."},{"value":"C","label":"Настройка профиля приложения","feedback":"Материал не посвящён настройке профиля приложения."},{"value":"D","label":"Администрирование пользователей","feedback":"Материал не посвящён административному разделу приложения."}],"correctValues":["A"],"hint":"Сверь формулировку вопроса с названием и кратким описанием урока."},{"id":"q2","type":"true_false","question":"Урок «Giant Candle» относится к разделу «Стратегии».","options":[{"value":"true","label":"Верно","feedback":"Урок действительно распределён в разделе «Стратегии»."},{"value":"false","label":"Неверно","feedback":"В структуре курса этот материал находится в разделе «Стратегии»."}],"correctValues":["true"],"hint":"Обрати внимание на учебный раздел, в котором расположен материал."},{"id":"q3","type":"multi_select","question":"Какие два утверждения прямо соответствуют описанию этого материала?","options":[{"value":"A","label":"В описании указан OTC и 5 секунд.","feedback":"Это утверждение прямо следует из исходного описания материала."},{"value":"B","label":"Сравнение идёт с 3–5 предыдущими свечами.","feedback":"Это утверждение также прямо указано в исходном описании."},{"value":"C","label":"Урок посвящён настройке интерфейса приложения.","feedback":"В исходном описании такого содержания нет."},{"value":"D","label":"Урок заменяет необходимость вести торговый журнал.","feedback":"Такого вывода исходный материал не содержит."}],"correctValues":["A","B"],"hint":"Выбирай только утверждения, которые можно подтвердить описанием этого урока."},{"id":"q4","type":"single_select","question":"Какой формат источника указан для материала «Giant Candle»?","options":[{"value":"A","label":"post","feedback":"В исходном списке материал указан как формат «post»."},{"value":"B","label":"software","feedback":"Это не формат данного источника."},{"value":"C","label":"dashboard","feedback":"Это не формат данного источника."},{"value":"D","label":"account","feedback":"Это не формат данного источника."}],"correctValues":["A"],"hint":"Смотри на тип исходного материала: видео, аудио, пост, книга или запись сессии."}],"keyTakeaway":"В описании указан OTC и 5 секунд.","facts":["В описании указан OTC и 5 секунд.","Сравнение идёт с 3–5 предыдущими свечами."],"sourceTitle":"Giant Candle","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":18,"curriculumVersion":"V31 FULL"}'::jsonb from public.learning_categories where slug='strategies' on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,lesson_type=excluded.lesson_type,duration_minutes=excluded.duration_minutes,sort_order=excluded.sort_order,status='published',category_id=excluded.category_id,content=excluded.content,updated_at=now();
