териала?","options":[{"value":"A","label":"Последовательность: зелёная–красная–зелёная.","feedback":"Это утверждение прямо следует из исходного описания материала."},{"value":"B","label":"Экспирация в описании — 2 минуты.","feedback":"Это утверждение также прямо указано в исходном описании."},{"value":"C","label":"Урок посвящён настройке интерфейса приложения.","feedback":"В исходном описании такого содержания нет."},{"value":"D","label":"Урок заменяет необходимость вести торговый журнал.","feedback":"Такого вывода исходный материал не содержит."}],"correctValues":["A","B"],"hint":"Выбирай только утверждения, которые можно подтвердить описанием этого урока."},{"id":"q4","type":"single_select","question":"Какой формат источника указан для материала «2-of-3»?","options":[{"value":"A","label":"post","feedback":"В исходном списке материал указан как формат «post»."},{"value":"B","label":"software","feedback":"Это не формат данного источника."},{"value":"C","label":"dashboard","feedback":"Это не формат данного источника."},{"value":"D","label":"account","feedback":"Это не формат данного источника."}],"correctValues":["A"],"hint":"Смотри на тип исходного материала: видео, аудио, пост, книга или запись сессии."}],"keyTakeaway":"Последовательность: зелёная–красная–зелёная.","facts":["Последовательность: зелёная–красная–зелёная.","Экспирация в описании — 2 минуты."],"sourceTitle":"2-of-3","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":19,"curriculumVersion":"V31 FULL"}'::jsonb from public.learning_categories where slug='strategies' on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,lesson_type=excluded.lesson_type,duration_minutes=excluded.duration_minutes,sort_order=excluded.sort_order,status='published',category_id=excluded.category_id,content=excluded.content,updated_at=now();
