":"q3","type":"multi_select","question":"Какие два утверждения прямо соответствуют описанию этого материала?","options":[{"value":"A","label":"Тема — соотношение риска и прибыли.","feedback":"Это утверждение прямо следует из исходного описания материала."},{"value":"B","label":"В описании упомянуты догоны и потеря контроля.","feedback":"Это утверждение также прямо указано в исходном описании."},{"value":"C","label":"Урок посвящён настройке интерфейса приложения.","feedback":"В исходном описании такого содержания нет."},{"value":"D","label":"Урок заменяет необходимость вести торговый журнал.","feedback":"Такого вывода исходный материал не содержит."}],"correctValues":["A","B"],"hint":"Выбирай только утверждения, которые можно подтвердить описанием этого урока."},{"id":"q4","type":"single_select","question":"Какой формат источника указан для материала «Как зарабатывать много с минимальными рисками?»?","options":[{"value":"A","label":"video","feedback":"В исходном списке материал указан как формат «video»."},{"value":"B","label":"software","feedback":"Это не формат данного источника."},{"value":"C","label":"dashboard","feedback":"Это не формат данного источника."},{"value":"D","label":"account","feedback":"Это не формат данного источника."}],"correctValues":["A"],"hint":"Смотри на тип исходного материала: видео, аудио, пост, книга или запись сессии."}],"keyTakeaway":"Тема — соотношение риска и прибыли.","facts":["Тема — соотношение риска и прибыли.","В описании упомянуты догоны и потеря контроля."],"sourceTitle":"Как зарабатывать много с минимальными рисками?","sourceDuration":"20 минут 33 секунды","lessonFormat":"video","sourceOrder":52,"curriculumVersion":"V31 FULL"}'::jsonb from public.learning_categories where slug='money-management' on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,lesson_type=excluded.lesson_type,duration_minutes=excluded.duration_minutes,sort_order=excluded.sort_order,status='published',category_id=excluded.category_