ал показывает авторский стиль торговли.","feedback":"Это утверждение прямо следует из исходного описания материала."},{"value":"B","label":"Затронуты ТА, ТП, РМ и мышление.","feedback":"Это утверждение также прямо указано в исходном описании."},{"value":"C","label":"Урок посвящён настройке интерфейса приложения.","feedback":"В исходном описании такого содержания нет."},{"value":"D","label":"Урок заменяет необходимость вести торговый журнал.","feedback":"Такого вывода исходный материал не содержит."}],"correctValues":["A","B"],"hint":"Выбирай только утверждения, которые можно подтвердить описанием этого урока."},{"id":"q4","type":"single_select","question":"Какой формат источника указан для материала «Как торгует Амир?»?","options":[{"value":"A","label":"video","feedback":"В исходном списке материал указан как формат «video»."},{"value":"B","label":"software","feedback":"Это не формат данного источника."},{"value":"C","label":"dashboard","feedback":"Это не формат данного источника."},{"value":"D","label":"account","feedback":"Это не формат данного источника."}],"correctValues":["A"],"hint":"Смотри на тип исходного материала: видео, аудио, пост, книга или запись сессии."}],"keyTakeaway":"Материал показывает авторский стиль торговли.","facts":["Материал показывает авторский стиль торговли.","Затронуты ТА, ТП, РМ и мышление."],"sourceTitle":"Как торгует Амир?","sourceDuration":"12 минут 6 секунд","lessonFormat":"video","sourceOrder":53,"curriculumVersion":"V31 FULL"}'::jsonb from public.learning_categories where slug='advanced' on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,lesson_type=excluded.lesson_type,duration_minutes=excluded.duration_minutes,sort_order=excluded.sort_order,status='published',category_id=excluded.category_id,content=excluded.content,updated_at=now();
